import type { Routes } from "@angular/router";
import { GALLIA_ROUTES } from "./provinces/gallia/gallia.routes";
import { HISPANIA_ROUTES } from "./provinces/hispania/hispania.routes";
import { AEGYPTUS_ROUTES } from "./provinces/aegyptus/aegyptus.routes";
import { DACIA_ROUTES } from "./provinces/dacia/dacia.routes";

export const routes: Routes = [
    { path: "", pathMatch: "full", redirectTo: "gallia/camps" },
    { path: "gallia", children: GALLIA_ROUTES },
    { path: "britannia", loadChildren: () => import("./provinces/britannia/britannia.routes").then(module => module.BRITANNIA_ROUTES) },
    { path: "hispania", children: HISPANIA_ROUTES },
    { path: "germania", loadChildren: () => import("./provinces/germania/germania.routes").then(module => module.GERMANIA_ROUTES) },
    { path: "aegyptus", children: AEGYPTUS_ROUTES },
    { path: "graecia", loadChildren: () => import("./provinces/graecia/graecia.routes").then(module => module.GRAECIA_ROUTES) },
    { path: "dacia", children: DACIA_ROUTES },
    { path: "syria", loadChildren: () => import("./provinces/syria/syria.routes").then(module => module.SYRIA_ROUTES) }
];
import { ChangeDetectionStrategy, Component } from "@angular/core";
import { RouterOutlet } from "@angular/router";

@Component({
    selector: "app-root",
    changeDetection: ChangeDetectionStrategy.OnPush,
    imports: [ RouterOutlet ],
    template: `<h1>Castra</h1><router-outlet />`
})
export class AppComponent {}
import { ChangeDetectionStrategy, Component } from "@angular/core";
import { EagleComponent } from "./widgets/eagle.component";
import { LegionRosterComponent } from "./widgets/legion-roster.component";
import { RationComponent } from "./widgets/ration.component";

@Component({
    selector: "app-old-dashboard-page",
    changeDetection: ChangeDetectionStrategy.OnPush,
    imports: [ LegionRosterComponent, EagleComponent, RationComponent ],
    template: `<app-legion-roster /><app-eagle /><app-ration [grain]="3" />`
})
export class OldDashboardPageComponent {}
